#### Component Example

```jsx
import React, { useEffect, useState } from 'react';

const UserProfile = ({ userId }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const response = await fetch(`/api/users/${userId}`);
        if (!response.ok) throw new Error('Failed to fetch');
        const data = await response.json();
        setUser(data);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    fetchUser();
  }, [userId]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;
  return <div>User: {user.name}</div>;
};

export default UserProfile;
```

#### Jest Test Cases

```javascript
import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import UserProfile from './UserProfile';

// Mock the global fetch function
global.fetch = jest.fn();

describe('UserProfile Component', () => {
  const userId = '123';

  beforeEach(() => {
    jest.clearAllMocks(); // Clear any previous mocks
  });

  it('displays loading initially', () => {
    render(<UserProfile userId={userId} />);
    expect(screen.getByText(/loading/i)).toBeInTheDocument();
  });

  it('displays user data after successful fetch', async () => {
    // Mocking a successful response
    fetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ name: 'John Doe' }),
    });

    render(<UserProfile userId={userId} />);

    // Wait for the user data to be rendered
    await waitFor(() => expect(screen.getByText(/User: John Doe/i)).toBeInTheDocument());
  });

  it('displays an error message on fetch failure', async () => {
    // Mocking a failed response
    fetch.mockResolvedValueOnce({ ok: false });

    render(<UserProfile userId={userId} />);

    // Wait for the error message to be rendered
    await waitFor(() => expect(screen.getByText(/Error: Failed to fetch/i)).toBeInTheDocument());
  });

  it('displays an error message on exception', async () => {
    // Mocking an exception
    fetch.mockRejectedValueOnce(new Error('Network error'));

    render(<UserProfile userId={userId} />);

    // Wait for the error message to be rendered
    await waitFor(() => expect(screen.getByText(/Error: Network error/i)).toBeInTheDocument());
  });
});
```

